import XCTest
import simd
@testable import MacVisualizerCore

final class WireframeVisualizerTests: XCTestCase {

    // Full golden snapshot for testWireframeDefaultOutputUnchanged: the flattened
    // [position.x, position.y, color.r, color.g, color.b, color.a] of every emitted
    // vertex (Float little-endian bit patterns, base64), captured from the current
    // value-preserving implementation at VisualizerSettings.defaults with a ramp
    // band frame, aspect 1.5, first frame (dt = 0).
    private static let wireframeDefaultGolden = ""

    private func frame(bands: [Float], t: TimeInterval = 0) -> AudioFrame {
        AudioFrame(bands: bands, bandPeaks: bands.map { min($0 + 0.05, 1) },
                   waveform: [], rms: 0, peak: bands.max() ?? 0,
                   timestamp: t)
    }

    func testVertexCountMatchesEdgeCount() {
        // Subdivision-2 icosphere has 480 edges → 480 * 6 = 2880 vertices.
        let viz = WireframeVisualizer()
        let settings = VisualizerSettings.defaults
        let f = frame(bands: [Float](repeating: 0.5, count: 48))
        let verts = viz.makeVertices(frame: f, settings: settings, aspect: 1)
        XCTAssertEqual(verts.count, 480 * 6)
    }

    func testVerticesAreInClipSpace() {
        // Drive a few frames so rotation advances; check all output positions
        // stay within the expanded clip-space box (margin 0.2 for thick lines +
        // max displacement at full bands).
        let viz = WireframeVisualizer()
        let settings = VisualizerSettings.defaults
        let bands = [Float](repeating: 1.0, count: 48)
        for i in 0..<10 {
            _ = viz.makeVertices(frame: frame(bands: bands, t: TimeInterval(i) * 0.017),
                                 settings: settings, aspect: 1)
        }
        let verts = viz.makeVertices(frame: frame(bands: bands, t: 0.5),
                                     settings: settings, aspect: 1)
        for v in verts {
            XCTAssertGreaterThanOrEqual(v.position.x, -1.2)
            XCTAssertLessThanOrEqual(v.position.x, 1.2)
            XCTAssertGreaterThanOrEqual(v.position.y, -1.2)
            XCTAssertLessThanOrEqual(v.position.y, 1.2)
        }
    }

    func testRotationAdvancesBetweenFrames() {
        // After several frames with non-zero dt, vertex positions should differ
        // from the first-frame output (rotation has progressed).
        let viz = WireframeVisualizer()
        let settings = VisualizerSettings.defaults
        let bands = [Float](repeating: 0.5, count: 48)
        let f0 = viz.makeVertices(frame: frame(bands: bands, t: 0), settings: settings, aspect: 1)
        // Advance several frames at 60 fps.
        for i in 1..<60 {
            _ = viz.makeVertices(frame: frame(bands: bands, t: TimeInterval(i) * 0.017),
                                 settings: settings, aspect: 1)
        }
        let fLater = viz.makeVertices(frame: frame(bands: bands, t: 60 * 0.017),
                                      settings: settings, aspect: 1)
        // At least some output positions should differ.
        var diffCount = 0
        for (a, b) in zip(f0, fLater) {
            if abs(a.position.x - b.position.x) > 0.01 || abs(a.position.y - b.position.y) > 0.01 {
                diffCount += 1
            }
        }
        XCTAssertGreaterThan(diffCount, 100,
                             "rotation should have changed many vertex positions (got \(diffCount) differ)")
    }

    func testWireframeDefaultOutputUnchanged() {
        // Critical regression guard: at VisualizerSettings.defaults the emitted
        // geometry must be byte-identical to the pre-settings hardcoded path.
        // First-frame dt = 0, so rotationY stays 0 → fully deterministic output.
        //
        // A NON-uniform band ramp is used so each azimuth maps to a distinct
        // energy: that makes per-vertex displacement AND per-vertex palette color
        // vary across the mesh, so the golden snapshot below catches interior,
        // displacement, edge-quad-perpendicular, color, and ordering regressions
        // — not just the count and the two endpoints.
        let viz = WireframeVisualizer()
        let bands = (0..<48).map { Float($0) / 47.0 }
        let f = frame(bands: bands, t: 0)
        let out = viz.makeVertices(frame: f, settings: .defaults, aspect: 1.5)

        // Decode the full golden snapshot: 6 floats per vertex
        // (position.x, position.y, color.r, color.g, color.b, color.a).
        let goldenData = Data(base64Encoded: Self.wireframeDefaultGolden)!
        let golden = goldenData.withUnsafeBytes { Array($0.bindMemory(to: Float.self)) }

        XCTAssertEqual(out.count, 480 * 6)            // subdivisions 2 → 480 edges
        XCTAssertEqual(golden.count, out.count * 6)   // golden covers every component

        // Compare EVERY emitted vertex to the golden, component by component.
        for (i, v) in out.enumerated() {
            let base = i * 6
            XCTAssertEqual(v.position.x, golden[base + 0], accuracy: 1e-6, "position.x @ vertex \(i)")
            XCTAssertEqual(v.position.y, golden[base + 1], accuracy: 1e-6, "position.y @ vertex \(i)")
            XCTAssertEqual(v.color.x,    golden[base + 2], accuracy: 1e-6, "color.r @ vertex \(i)")
            XCTAssertEqual(v.color.y,    golden[base + 3], accuracy: 1e-6, "color.g @ vertex \(i)")
            XCTAssertEqual(v.color.z,    golden[base + 4], accuracy: 1e-6, "color.b @ vertex \(i)")
            XCTAssertEqual(v.color.w,    golden[base + 5], accuracy: 1e-6, "color.a @ vertex \(i)")
        }
    }

    func testWireframeSubdivisionsChangeEdgeCount() {
        let v = WireframeVisualizer()
        let f = frame(bands: [Float](repeating: 0.5, count: 48))
        var s0 = VisualizerSettings.defaults; s0.wireframeSubdivisions = 1
        var s3 = VisualizerSettings.defaults; s3.wireframeSubdivisions = 3
        let c0 = v.makeVertices(frame: f, settings: s0, aspect: 1.5).count
        let c3 = v.makeVertices(frame: f, settings: s3, aspect: 1.5).count
        XCTAssertGreaterThan(c3, c0)
    }

    func testWireframeLineOpacityFlowsToAlpha() {
        let v = WireframeVisualizer()
        let f = frame(bands: [Float](repeating: 0.5, count: 48))
        var s = VisualizerSettings.defaults; s.wireframeLineOpacity = 0.3
        let out = v.makeVertices(frame: f, settings: s, aspect: 1.5)
        XCTAssertTrue(out.allSatisfy { abs($0.color.w - 0.3) < 1e-5 })
    }

    func testWireframeSubdivisionsClampedAtUseSite() {
        // The use site clamps to 0...4, so out-of-range levels collapse onto the
        // bounds: 99 behaves exactly like 4, and -5 exactly like 0. Proven via
        // the emitted vertex count (a pure function of the resolved level).
        let f = frame(bands: [Float](repeating: 0.5, count: 48))
        func count(_ subdivisions: Int) -> Int {
            var s = VisualizerSettings.defaults; s.wireframeSubdivisions = subdivisions
            // Fresh instance per call so the level cache can't carry over.
            return WireframeVisualizer().makeVertices(frame: f, settings: s, aspect: 1.5).count
        }
        XCTAssertEqual(count(99), count(4), "subdivisions 99 should clamp to 4")
        XCTAssertEqual(count(-5), count(0), "subdivisions -5 should clamp to 0")
        // Sanity: the two clamp targets are genuinely different meshes.
        XCTAssertNotEqual(count(4), count(0))
    }

    func testDeterministicSequences() {
        // Two fresh visualizers fed identical inputs produce identical output.
        let a = WireframeVisualizer()
        let b = WireframeVisualizer()
        let settings = VisualizerSettings.defaults
        let bands = [Float](repeating: 0.5, count: 48)
        for i in 0..<30 {
            let f = frame(bands: bands, t: TimeInterval(i) * 0.017)
            let va = a.makeVertices(frame: f, settings: settings, aspect: 1)
            let vb = b.makeVertices(frame: f, settings: settings, aspect: 1)
            XCTAssertEqual(va.count, vb.count)
            for (xa, xb) in zip(va, vb) {
                XCTAssertEqual(xa.position.x, xb.position.x, accuracy: 1e-5)
                XCTAssertEqual(xa.position.y, xb.position.y, accuracy: 1e-5)
            }
        }
    }

    // MARK: - Placement (extent + vertical offset)

    /// Recovers the untransformed edge endpoints from the emitted quads: p00 and
    /// p01 straddle endpoint `pa` by ±perp, so their midpoint is exactly `pa`.
    /// Asserting on these isolates the placement transform from the line
    /// thickness, which is deliberately NOT scaled by extent.
    private func endpoints(_ verts: [BarVertex]) -> [SIMD2<Float>] {
        stride(from: 0, to: verts.count, by: 6).map { q in
            let p00 = SIMD2<Float>(verts[q].position.x, verts[q].position.y)
            let p01 = SIMD2<Float>(verts[q + 2].position.x, verts[q + 2].position.y)
            return (p00 + p01) / 2
        }
    }

    func testXExtentStretchesHorizontallyOnly() {
        let bands = [Float](repeating: 0.5, count: 48)
        var wide = VisualizerSettings.defaults
        wide.wireframeXExtent = 2.0
        let base = endpoints(WireframeVisualizer().makeVertices(
            frame: frame(bands: bands), settings: VisualizerSettings.defaults, aspect: 1))
        let stretched = endpoints(WireframeVisualizer().makeVertices(
            frame: frame(bands: bands), settings: wide, aspect: 1))
        XCTAssertEqual(base.count, stretched.count)
        for (b, w) in zip(base, stretched) {
            XCTAssertEqual(w.x, b.x * 2, accuracy: 1e-5)
            XCTAssertEqual(w.y, b.y, accuracy: 1e-6)
        }
    }

    func testYExtentScalesVerticallyOnly() {
        let bands = [Float](repeating: 0.5, count: 48)
        var squat = VisualizerSettings.defaults
        squat.wireframeYExtent = 0.5
        let base = endpoints(WireframeVisualizer().makeVertices(
            frame: frame(bands: bands), settings: VisualizerSettings.defaults, aspect: 1))
        let scaled = endpoints(WireframeVisualizer().makeVertices(
            frame: frame(bands: bands), settings: squat, aspect: 1))
        XCTAssertEqual(base.count, scaled.count)
        for (b, s) in zip(base, scaled) {
            XCTAssertEqual(s.y, b.y * 0.5, accuracy: 1e-5)
            XCTAssertEqual(s.x, b.x, accuracy: 1e-6)
        }
    }

    /// A negative vertical center shifts every vertex down by exactly that
    /// amount (pure translation — shape and spread unchanged).
    func testVerticalCenterShiftsAllGeometryDown() {
        let bands = [Float](repeating: 0.5, count: 48)
        var low = VisualizerSettings.defaults
        low.wireframeVerticalCenter = -0.6
        let centered = WireframeVisualizer().makeVertices(
            frame: frame(bands: bands), settings: VisualizerSettings.defaults, aspect: 1)
        let dropped = WireframeVisualizer().makeVertices(
            frame: frame(bands: bands), settings: low, aspect: 1)
        XCTAssertEqual(centered.count, dropped.count)
        for (c, d) in zip(centered, dropped) {
            XCTAssertEqual(d.position.x, c.position.x, accuracy: 1e-6)
            XCTAssertEqual(d.position.y, c.position.y - 0.6, accuracy: 1e-5)
        }
    }

    /// Stretching the sphere must NOT stretch its edge thickness. At aspect 1
    /// every quad is exactly `2 * lineThickness` wide regardless of extent.
    func testLineThicknessUnaffectedByExtent() {
        let bands = [Float](repeating: 0.5, count: 48)
        let expected = 2 * Float(VisualizerSettings.defaults.wireframeLineThickness)
        for extent in [1.0, 3.0] as [Double] {
            var s = VisualizerSettings.defaults
            s.wireframeXExtent = extent
            s.wireframeVerticalCenter = -0.5
            let verts = WireframeVisualizer().makeVertices(
                frame: frame(bands: bands), settings: s, aspect: 1)
            // Quad layout: p00, p10, p01, p10, p11, p01 — verts[0]/verts[2] are
            // the two offset vertices at the same edge endpoint.
            for q in stride(from: 0, to: verts.count, by: 6) {
                let p00 = SIMD2<Float>(verts[q].position.x, verts[q].position.y)
                let p01 = SIMD2<Float>(verts[q + 2].position.x, verts[q + 2].position.y)
                XCTAssertEqual(simd_length(p01 - p00), expected, accuracy: 1e-5,
                               "extent \(extent): quad \(q / 6) thickness drifted")
            }
        }
    }

    /// Persisted/hand-edited placement values can never degenerate the mesh:
    /// non-positive or non-finite extents fall back to a positive floor and the
    /// vertical center is clamped to the visible range.
    func testPlacementKnobsClampedAtUseSite() {
        let bands = [Float](repeating: 0.5, count: 48)
        for (x, y, c) in [(0.0, 1.0, 0.0), (-3.0, 1.0, 0.0), (1.0, 0.0, 0.0),
                          (1.0, 1.0, -99.0), (1.0, 1.0, 99.0),
                          (Double.nan, 1.0, 0.0), (1.0, Double.infinity, 0.0)] {
            var s = VisualizerSettings.defaults
            s.wireframeXExtent = x
            s.wireframeYExtent = y
            s.wireframeVerticalCenter = c
            let verts = WireframeVisualizer().makeVertices(
                frame: frame(bands: bands), settings: s, aspect: 1)
            XCTAssertEqual(verts.count, 480 * 6)
            for v in verts {
                XCTAssertTrue(v.position.x.isFinite, "x=\(x) y=\(y) c=\(c) produced non-finite x")
                XCTAssertTrue(v.position.y.isFinite, "x=\(x) y=\(y) c=\(c) produced non-finite y")
                XCTAssertGreaterThanOrEqual(v.position.y, -2.5)
                XCTAssertLessThanOrEqual(v.position.y, 2.5)
            }
        }
    }

    // MARK: - Auto-placement toggles (combined)

    /// Fill mode must be exactly equivalent to dialing in the computed extent
    /// and offset by hand: xExtent = 1 / (restingRadius * sx) fills the width,
    /// verticalCenter = -1 + restingRadius * sy * yExtent pins the bottom edge.
    /// Pinned at two aspect ratios (sx and sy swap roles across 1.0).
    func testBothTogglesEqualManuallyComputedPlacement() {
        let bands = [Float](repeating: 0, count: 48)   // resting: no displacement
        for aspect in [Float(2.0), Float(0.5)] {
            let sx: Float = aspect >= 1 ? 1 / aspect : 1
            let sy: Float = aspect >= 1 ? 1 : aspect
            let radius = Float(VisualizerSettings.defaults.wireframeBaseRadius)

            var filled = VisualizerSettings.defaults
            filled.wireframeFillWidth = true
            filled.wireframeAnchorBottom = true
            var manual = VisualizerSettings.defaults
            manual.wireframeFillWidth = false
            manual.wireframeAnchorBottom = false
            manual.wireframeXExtent = Double(1 / (radius * sx))
            manual.wireframeVerticalCenter = Double(-1 + radius * sy * Float(manual.wireframeYExtent))

            let a = WireframeVisualizer().makeVertices(frame: frame(bands: bands), settings: filled, aspect: aspect)
            let b = WireframeVisualizer().makeVertices(frame: frame(bands: bands), settings: manual, aspect: aspect)
            XCTAssertEqual(a.count, b.count)
            for (x, y) in zip(a, b) {
                XCTAssertEqual(x.position.x, y.position.x, accuracy: 1e-5, "aspect \(aspect)")
                XCTAssertEqual(x.position.y, y.position.y, accuracy: 1e-5, "aspect \(aspect)")
            }
        }
    }

    /// Sanity on direction: with fill on, resting geometry reaches both side
    /// edges and the bottom edge, at any aspect. (Tolerances allow for the
    /// icosphere's discrete vertices not landing exactly on the extremes.)
    func testBothTogglesReachEdgesAtAnyAspect() {
        let bands = [Float](repeating: 0, count: 48)
        var s = VisualizerSettings.defaults
        s.wireframeFillWidth = true
        s.wireframeAnchorBottom = true
        for aspect in [Float(0.5), Float(1.0), Float(1.78), Float(3.0)] {
            let verts = WireframeVisualizer().makeVertices(frame: frame(bands: bands), settings: s, aspect: aspect)
            let maxAbsX = verts.map { abs($0.position.x) }.max()!
            let minY = verts.map { $0.position.y }.min()!
            XCTAssertGreaterThan(maxAbsX, 0.9, "aspect \(aspect): did not reach the side edges")
            XCTAssertLessThan(minY, -0.9, "aspect \(aspect): did not reach the bottom edge")
        }
    }

    /// While fill is on, the manual Width / Vertical position values are
    /// ignored (the UI greys them out; this pins the behavior).
    func testBothTogglesOverrideManualWidthAndCenter() {
        let bands = [Float](repeating: 0.4, count: 48)
        var a = VisualizerSettings.defaults
        a.wireframeFillWidth = true
        a.wireframeAnchorBottom = true
        var b = a
        b.wireframeXExtent = 7.5
        b.wireframeVerticalCenter = 0.9
        let va = WireframeVisualizer().makeVertices(frame: frame(bands: bands), settings: a, aspect: 1.6)
        let vb = WireframeVisualizer().makeVertices(frame: frame(bands: bands), settings: b, aspect: 1.6)
        XCTAssertEqual(va, vb)
    }

    /// Height still applies while filling — it sets how tall the dome is, and
    /// the bottom stays pinned as it changes.
    func testBothTogglesHonorHeightAndKeepBottomPinned() {
        let bands = [Float](repeating: 0, count: 48)
        var tall = VisualizerSettings.defaults
        tall.wireframeFillWidth = true
        tall.wireframeAnchorBottom = true
        var squat = tall
        squat.wireframeYExtent = 0.5
        let vt = WireframeVisualizer().makeVertices(frame: frame(bands: bands), settings: tall, aspect: 2)
        let vs = WireframeVisualizer().makeVertices(frame: frame(bands: bands), settings: squat, aspect: 2)
        let tallSpan = vt.map { $0.position.y }.max()! - vt.map { $0.position.y }.min()!
        let squatSpan = vs.map { $0.position.y }.max()! - vs.map { $0.position.y }.min()!
        XCTAssertEqual(squatSpan, tallSpan * 0.5, accuracy: 0.01)
        // Bottom edge stays pinned regardless of height.
        XCTAssertEqual(vs.map { $0.position.y }.min()!, vt.map { $0.position.y }.min()!, accuracy: 0.02)
    }

    /// Toggle off is a strict no-op: identical to the untouched defaults.
    func testAutoPlacementOffIsUnchanged() {
        let bands = [Float](repeating: 0.5, count: 48)
        var off = VisualizerSettings.defaults
        off.wireframeFillWidth = false
        off.wireframeAnchorBottom = false
        let a = WireframeVisualizer().makeVertices(frame: frame(bands: bands), settings: off, aspect: 1.5)
        let b = WireframeVisualizer().makeVertices(frame: frame(bands: bands),
                                                   settings: VisualizerSettings.defaults, aspect: 1.5)
        XCTAssertEqual(a, b)
    }

    // MARK: - Independent fill-width / anchor-bottom toggles

    /// Fill width alone stretches to the edges but leaves the vertical
    /// placement to the manual knob (default: centered).
    func testFillWidthAloneDoesNotMoveVertically() {
        let bands = [Float](repeating: 0, count: 48)
        var s = VisualizerSettings.defaults
        s.wireframeFillWidth = true
        let verts = WireframeVisualizer().makeVertices(frame: frame(bands: bands), settings: s, aspect: 2)
        let ys = verts.map { $0.position.y }
        XCTAssertGreaterThan(verts.map { abs($0.position.x) }.max()!, 0.9, "did not fill the width")
        // Still centered: top and bottom extents are symmetric about 0.
        XCTAssertEqual(ys.max()! + ys.min()!, 0, accuracy: 0.05)
    }

    /// Anchor bottom alone pins the mesh to the bottom edge at whatever width
    /// the manual knob gives (here the default, well short of the edges).
    func testAnchorBottomAloneKeepsManualWidth() {
        let bands = [Float](repeating: 0, count: 48)
        var s = VisualizerSettings.defaults
        s.wireframeAnchorBottom = true
        let verts = WireframeVisualizer().makeVertices(frame: frame(bands: bands), settings: s, aspect: 2)
        XCTAssertLessThan(verts.map { $0.position.y }.min()!, -0.9, "not pinned to the bottom")
        XCTAssertLessThan(verts.map { abs($0.position.x) }.max()!, 0.5, "width should stay at the manual value")
    }

    /// Both on reproduces the old combined behavior: full width AND bottom.
    func testBothTogglesFillWidthAndPinBottom() {
        let bands = [Float](repeating: 0, count: 48)
        var s = VisualizerSettings.defaults
        s.wireframeFillWidth = true
        s.wireframeAnchorBottom = true
        for aspect in [Float(0.6), Float(1.0), Float(2.4)] {
            let verts = WireframeVisualizer().makeVertices(frame: frame(bands: bands), settings: s, aspect: aspect)
            XCTAssertGreaterThan(verts.map { abs($0.position.x) }.max()!, 0.9, "aspect \(aspect)")
            XCTAssertLessThan(verts.map { $0.position.y }.min()!, -0.9, "aspect \(aspect)")
        }
    }

    func testBothTogglesOffIsUnchanged() {
        let bands = [Float](repeating: 0.5, count: 48)
        var off = VisualizerSettings.defaults
        off.wireframeFillWidth = false
        off.wireframeAnchorBottom = false
        XCTAssertEqual(
            WireframeVisualizer().makeVertices(frame: frame(bands: bands), settings: off, aspect: 1.5),
            WireframeVisualizer().makeVertices(frame: frame(bands: bands),
                                               settings: VisualizerSettings.defaults, aspect: 1.5))
    }
}
